// ============================================
// VALIDATION INPUT - Summarizer
// ============================================

const input = $input.first().json;
const body = input.body || input;

// Support RFC-014: data in context.* with fallback to root level
const ctx = body.context || {};

const errors = [];

// --- Required field ---
const text = body.text || ctx.text;
if (!text || typeof text !== 'string' || text.trim().length === 0) {
  errors.push('text requis (chaine non vide)');
}

// --- Context fields for tracing ---
const userId = body.user_id || ctx.user_id || null;
const guildId = body.guild_id || ctx.guild_id || null;
const userRequest = body.user_request || ctx.user_request || null;

// --- Optional parameters ---
const style = body.style || ctx.style || null;
const maxLength = body.max_length || ctx.max_length || null;
const language = body.language || ctx.language || null;
const maxTokens = parseInt(body.max_tokens || ctx.max_tokens || 1024);
const executionMode = body.execution_mode || ctx.execution_mode || 'online';

// Validate style if provided
const validStyles = ['brief', 'detailed', 'bullet-points'];
if (style && !validStyles.includes(style)) {
  errors.push(`style invalide: ${style} (doit etre: ${validStyles.join(', ')})`);
}

// --- API Key from env or request ---
const anthropicKey = body.anthropic_api_key || body.plugin_context?.api_keys?.anthropic || $env.ANTHROPIC_API_KEY || '';

if (errors.length > 0) {
  return {
    valid: false,
    errors: errors,
    user_id: userId,
    guild_id: guildId,
    user_request: userRequest
  };
}

return {
  valid: true,
  text: text.trim(),
  style: style,
  max_length: maxLength,
  language: language,
  max_tokens: maxTokens,
  execution_mode: executionMode,
  user_id: userId,
  guild_id: guildId,
  user_request: userRequest,
  anthropicKey: anthropicKey,
  startTime: Date.now()
};

// ============================================
// BUILD VALIDATION ERROR
// ============================================

const input = $input.first().json;

return {
  success: false,
  _trace: {
    service_response: { validation_errors: input.errors },
    provider: 'none',
    mode: 'error',
    latency_ms: 0,
    user_id: input.user_id,
    guild_id: input.guild_id,
    user_request: input.user_request
  },
  error: {
    code: 'VALIDATION_ERROR',
    message: input.errors.join(', '),
    http_status: 400
  },
  user_id: input.user_id,
  guild_id: input.guild_id,
  user_request: input.user_request
};

// ============================================
// PREPARE PROMPT - Summarizer
// ============================================

const data = $input.first().json;

let prompt = 'Summarize the following text';

if (data.style) {
  prompt += ` in a ${data.style} style`;
}
if (data.max_length) {
  prompt += ` in approximately ${data.max_length} words`;
}
if (data.language) {
  prompt += ` in ${data.language}`;
}
if (data.user_request) {
  prompt += `. User context: ${data.user_request}`;
}

prompt += `:\n\n${data.text}\n\nProvide a clear, concise summary that captures the main points.`;

return {
  prompt: prompt,
  original_length: data.text.length,
  text: data.text,
  style: data.style,
  max_tokens: data.max_tokens,
  execution_mode: data.execution_mode,
  user_id: data.user_id,
  guild_id: data.guild_id,
  user_request: data.user_request,
  anthropicKey: data.anthropicKey,
  startTime: data.startTime
};

// ============================================
// FORMAT OUTPUT - Summarizer
// ============================================

const input = $input.first().json;
const prevData = $('Prepare Prompt').first().json;
const startTime = prevData.startTime || Date.now();

const userId = prevData.user_id;
const guildId = prevData.guild_id;
const userRequest = prevData.user_request;

// Handle error response
if (input.error || input.type === 'error') {
  return {
    success: false,
    error: {
      code: 'LLM_ERROR',
      message: input.error?.message || 'Anthropic API error',
      http_status: 500
    },
    user_id: userId,
    guild_id: guildId,
    user_request: userRequest,
    _trace: {
      llm_response: null,
      service_response: input,
      provider: 'anthropic',
      model: 'claude-haiku-4-5-20251001',
      tokens: { input: 0, output: 0 },
      latency_ms: Date.now() - startTime,
      user_id: userId,
      guild_id: guildId,
      user_request: userRequest
    }
  };
}

const summary = input.content?.[0]?.text || '';
const originalLength = prevData.original_length;
const summaryLength = summary.length;
const compressionRatio = originalLength > 0 ? Math.round((originalLength / summaryLength) * 100) / 100 : 0;

const _trace = {
  llm_response: summary,
  service_response: input,
  provider: 'anthropic',
  model: input.model || 'claude-haiku-4-5-20251001',
  tokens: {
    input: input.usage?.input_tokens || 0,
    output: input.usage?.output_tokens || 0
  },
  latency_ms: Date.now() - startTime,
  user_id: userId,
  guild_id: guildId,
  user_request: userRequest
};

return {
  success: true,
  data: {
    summary: summary,
    original_length: originalLength,
    summary_length: summaryLength,
    compression_ratio: compressionRatio
  },
  meta: {
    provider: 'anthropic',
    model: input.model || 'claude-haiku-4-5-20251001',
    execution_mode: prevData.execution_mode || 'online',
    usage: {
      input_tokens: input.usage?.input_tokens || 0,
      output_tokens: input.usage?.output_tokens || 0
    }
  },
  user_id: userId,
  guild_id: guildId,
  user_request: userRequest,
  _trace: _trace
};

